using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class DiscoveryTests {
  static int failures,count;
  static void Check(bool v,string s){count++;if(!v)failures++;Console.WriteLine((v?"PASS: ":"FAIL: ")+s);}
  static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
  static string Game(string path){Put(Path.Combine(path,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(path,"ProjectZomboid64.exe"),"inert fixture, never run");return path;}
  static string Manifest(string root,string name){string file=Path.Combine(root,"steamapps","appmanifest_108600.acf");Put(file,"\"AppState\" { \"installdir\" \""+name+"\" }");return file;}
  static string Call(string name,params object[] args){var method=typeof(GameDiscovery).GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static,null,args.Select(x=>x.GetType()).ToArray(),null);if(method==null){Check(false,"discovery API exists: "+name);return "";}return (string)method.Invoke(null,args);}
  public static void Run(){failures=0;count=0;string root=Path.Combine(LauncherTestPaths.Root,"discovery-"+Guid.NewGuid().ToString("N")),steam=Path.Combine(root,"steam client"),library=Path.Combine(root,"游戏库 Library"),game=Game(Path.Combine(library,"steamapps","common","自定义 PZ Folder"));Manifest(library,"自定义 PZ Folder");string vdf=Path.Combine(steam,"steamapps","libraryfolders.vdf");
   // Breaks caught: lost modern/legacy libraries, wrong manifest names, or incomplete installs accepted.
   Put(vdf,"\"libraryfolders\" { \"1\" { \"path\" \""+library.Replace("\\","\\\\")+"\" } }");Check(GameDiscovery.Find(new[]{steam})==game,"modern VDF custom Unicode install");Put(vdf,"\"LibraryFolders\" { \"1\" \""+library.Replace("\\","\\\\")+"\" }");Check(GameDiscovery.Find(new[]{steam})==game,"legacy VDF custom install");
   File.Delete(Path.Combine(game,"ProjectZomboid64.exe"));Check(GameDiscovery.Find(new[]{library})=="","missing executable rejected");Game(game);File.Delete(Path.Combine(game,"ProjectZomboid64.json"));Check(GameDiscovery.Find(new[]{library})=="","missing JSON rejected");Game(game);
   Check(GameDiscovery.Find(null)==""&&GameDiscovery.Find(new string[0])=="","explicit empty roots never read host environment");
   // Break caught: crafted manifest traverses or normalizes into a parent / non-direct child.
   string bad=Path.Combine(root,"bad");foreach(string name in new[]{".","..","Folder.","Folder ","/absolute","C:relative","C:\\absolute","one/two","one\\two","bad:name","bad*name","bad?name","bad|name","bad<name","bad>name"}){Game(Path.Combine(bad,"steamapps","common"));Game(Path.Combine(bad,"steamapps"));Manifest(bad,name);Check(GameDiscovery.Find(new[]{bad})=="","malformed installdir refused: "+name);}
   Check(Call("ResolveSelection",library)==game,"selected library resolves custom install");Check(Call("ResolveSelection",Path.Combine(library,"steamapps"))==game,"steamapps parent resolves manifest");Check(Call("ResolveSelection",Path.Combine(library,"steamapps","common"))==game,"common parent resolves manifest");Check(Call("ResolveSelection",steam)==game,"Steam root resolves library metadata");Check(Call("ResolveSelection",game)==game,"exact game selected");Check(Call("ResolveSelection",Path.Combine(game,"ProjectZomboid64.exe"))==game,"exact exe resolves containing game");Check(Call("ResolveSelection",Path.Combine(game,"ProjectZomboid64.json"))=="","arbitrary file not treated as game selection");Game(Path.Combine(root,"unrelated","deep","ProjectZomboid"));Check(Call("ResolveSelection",Path.Combine(root,"unrelated"))=="","selection never searches arbitrary descendants");
   // Breaks caught: unreadable/oversized/invalid metadata prevents later candidates or silently decodes.
   string fallback=Path.Combine(root,"SteamLibrary"),fallbackGame=Game(Path.Combine(fallback,"steamapps","common","ProjectZomboid"));Put(vdf,new string('x',1048577));Check(GameDiscovery.Find(new[]{steam,library})==game,"oversized VDF skips to good root");Put(vdf,"\"path\" \""+library.Replace("\\","\\\\")+"\"");using(var held=new FileStream(vdf,FileMode.Open,FileAccess.Read,FileShare.None))Check(GameDiscovery.Find(new[]{steam,library})==game,"locked VDF skips to good root");File.WriteAllBytes(vdf,new byte[]{255,255});Check(GameDiscovery.Find(new[]{steam})=="","invalid UTF8 VDF refused");Put(vdf,"\"path\" \""+library.Replace("\\","\\\\")+"\"");string manifest=Manifest(library,"自定义 PZ Folder");Put(manifest,new string('x',262145));Check(GameDiscovery.Find(new[]{library,fallback})==fallbackGame,"oversized manifest skips to good root");Manifest(library,"自定义 PZ Folder");using(var held=new FileStream(manifest,FileMode.Open,FileAccess.Read,FileShare.None))Check(GameDiscovery.Find(new[]{library,fallback})==fallbackGame,"locked manifest skips to good root");
   var many=Enumerable.Range(0,128).Select(i=>Path.Combine(root,"absent"+i)).Concat(new[]{fallback}).ToArray();Check(GameDiscovery.Find(many)=="","distinct roots capped at 128");Check(GameDiscovery.Find(Enumerable.Repeat(library,150).ToArray())==game,"canonical duplicate roots do not exhaust cap");
   // Breaks caught: stale/unreadable preference crashes startup, host roots leak into injection, or saved manual choice loses priority.
   string preference=Path.Combine(root,"preferences","game-path.txt"),manual=Game(Path.Combine(root,"portable"));Check(Call("InitialGame",preference,new string[0],new[]{fallback})==fallbackGame,"missing registry uses injected conventional fallback");Check(Call("InitialGame",preference,new[]{Path.Combine(root,"stale")},new[]{fallback})==fallbackGame,"stale registered roots use conventional fallback");Put(preference,manual);Check(Call("InitialGame",preference,new[]{library},new[]{fallback})==manual,"valid saved folder wins");Put(preference,library);Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"saved preference must be direct game folder");Put(preference,Path.Combine(root,"removed"));Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"stale preference falls back");Put(preference,new string('x',4097));Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"oversized preference falls back");Put(preference,manual);using(var held=new FileStream(preference,FileMode.Open,FileAccess.Read,FileShare.None))Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"locked preference falls back");File.WriteAllBytes(preference,new byte[]{255});Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"invalid UTF8 preference falls back");
   string link=Path.Combine(root,"junction");var start=new System.Diagnostics.ProcessStartInfo("cmd.exe","/c mklink /J \""+link+"\" \""+library+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=System.Diagnostics.Process.Start(start)){p.StandardOutput.ReadToEnd();string error=p.StandardError.ReadToEnd();if(!p.WaitForExit(5000)||p.ExitCode!=0)throw new Exception("Fixture junction failed: "+error);}Check(GameDiscovery.Find(new[]{link})=="","automatic discovery refuses reparse root");Check(Call("ResolveSelection",Path.Combine(link,"steamapps","common","自定义 PZ Folder"))=="","manual selection refuses reparse ancestor");Put(preference,Path.Combine(link,"steamapps","common","自定义 PZ Folder"));Check(Call("InitialGame",preference,new[]{fallback},new string[0])==fallbackGame,"reparse saved path falls back");
   Check(Call("InitialGame",Path.Combine(root,"missing-preference"),new[]{steam},new[]{fallback})==game,"registered manifest library wins over conventional fallback");ControllerSelection(root,library,game);ControllerRecoverySelection(root,library,game);Console.WriteLine("DISCOVERY ASSERTIONS: "+count+", FAILURES: "+failures);if(failures!=0)throw new Exception("Discovery failures: "+failures);
  }
  static void ControllerSelection(string root,string library,string game){string data=Path.Combine(root,"controller-data"),user=Path.Combine(root,"user"),preference=Path.Combine(data,"game-path.txt"),before=Game(Path.Combine(root,"controller-before"));Put(preference,before);using(var c=new ModernController(before,user,data,true)){bool selected=true;try{c.Execute("setGame",new Dictionary<string,object>{{"path",library}});}catch{selected=false;}Check(selected&&File.ReadAllText(preference)==game,"controller resolves library before persisting");var json=new JavaScriptSerializer();var status=json.Deserialize<Dictionary<string,object>>(json.Serialize(c.Execute("status",null)));Check((string)status["gamePath"]==game,"controller switches to resolved root");string saved=File.ReadAllText(preference);bool refused=false;try{c.Execute("setGame",new Dictionary<string,object>{{"path",Path.Combine(root,"wrong")}});}catch{refused=true;}status=json.Deserialize<Dictionary<string,object>>(json.Serialize(c.Execute("status",null)));Check(refused&&File.ReadAllText(preference)==saved&&(string)status["gamePath"]==game,"failed selection preserves preference and engine");}}
  // Break caught: parent metadata changes after recovery-owner admission redirect selection to another game.
  static void ControllerRecoverySelection(string root,string library,string owner){string data=Path.Combine(root,"pending-data"),user=Path.Combine(root,"pending-user"),other=Game(Path.Combine(root,"pending-other")),journal=PlayProfileTransaction.Journal(new Engine(owner,user,data,true));Put(journal,"{}");byte[] ownerBytes=File.ReadAllBytes(Path.Combine(owner,"ProjectZomboid64.json"));string redirected=Game(Path.Combine(library,"steamapps","common","Redirected"));using(var c=new ModernController(other,user,data,true)){bool denied=false;try{c.Execute("setGame",new Dictionary<string,object>{{"path",other}});}catch{denied=true;}Check(denied,"pending transaction still rejects unrelated selected root");c.Progress=(value,text)=>Manifest(library,"Redirected");bool selected=true;try{c.Execute("setGame",new Dictionary<string,object>{{"path",library}});}catch{selected=false;}var json=new JavaScriptSerializer();var status=json.Deserialize<Dictionary<string,object>>(json.Serialize(c.Execute("status",null)));Check(selected&&(string)status["gamePath"]==owner&&File.ReadAllText(Path.Combine(data,"game-path.txt"))==owner,"parent recovery-owner admission and persistence use same resolved root");Check(File.ReadAllText(journal)=="{}"&&File.ReadAllBytes(Path.Combine(owner,"ProjectZomboid64.json")).SequenceEqual(ownerBytes),"recovery-owner selection never restores game bytes or journal");}Manifest(library,"自定义 PZ Folder");}
  public static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
